{
  "version": "3.0.0",
  "status": "proposed_not_benchmarked",
  "provenance": "IDs and topic names from supplied design v1.1 pp. 7-9. Definitions condensed; routing rules are proposed engineering guidance. Referenced companion JSON was not supplied.",
  "hierarchy": "domain_to_topic; topic is the only subdomain level",
  "domain_assignment": "derived as union of selected topic domains; never model-invented",
  "domains": [
    {
      "id": "climate",
      "name": "Climate & disaster policy"
    },
    {
      "id": "energy",
      "name": "Energy"
    },
    {
      "id": "agriculture",
      "name": "Agriculture"
    },
    {
      "id": "water",
      "name": "Water"
    },
    {
      "id": "biodiversity",
      "name": "Biodiversity"
    },
    {
      "id": "health",
      "name": "Health"
    },
    {
      "id": "urban",
      "name": "Urban"
    },
    {
      "id": "waste",
      "name": "Waste"
    },
    {
      "id": "transport",
      "name": "Transport"
    },
    {
      "id": "industry",
      "name": "Industry"
    },
    {
      "id": "tourism",
      "name": "Tourism"
    }
  ],
  "topics": [
    {
      "id": "CLM-01",
      "name": "Climate planning and governance",
      "definition": "Strategies, plans, laws, institutional coordination and mainstreaming.",
      "routing_rule": "A finance mechanism also needs CLM-02; do not tag all climate text here.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "CLM-02",
      "name": "Climate finance and support",
      "definition": "Funding mechanisms, investment planning, budget integration, insurance and international support.",
      "routing_rule": "A funding source alone does not establish conditionality.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "CLM-03",
      "name": "Climate information and risk assessment",
      "definition": "Observations, scenarios, vulnerability assessments, risk maps and climate services.",
      "routing_rule": "Use CLM-04 for operational warnings and preparedness.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "CLM-04",
      "name": "Early warning and disaster preparedness",
      "definition": "Warnings, emergency planning, evacuation, civil protection and disaster readiness.",
      "routing_rule": "Do not infer operational warning capacity from a risk study.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "CLM-05",
      "name": "Climate monitoring and reporting",
      "definition": "GHG inventories, transparency, adaptation indicators, evaluation and reporting.",
      "routing_rule": "An expected monitoring indicator is not evidence of a result.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "CLM-06",
      "name": "Economy-wide emissions targets",
      "definition": "National emissions ceilings, reduction pledges, net-zero and economy-wide intensity targets.",
      "routing_rule": "Sectoral targets use the relevant sector topic; keep EU-wide scope explicit.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "CLM-07",
      "name": "Land carbon and removals",
      "definition": "Sequestration, land-use emissions/removals, forest carbon and LULUCF accounting.",
      "routing_rule": "Carbon-sink wording alone does not establish biodiversity benefits.",
      "domain_ids": [
        "climate"
      ]
    },
    {
      "id": "ENE-01",
      "name": "Renewable electricity",
      "definition": "Solar, wind, hydropower and other renewable electricity, including distributed generation.",
      "routing_rule": "Rooftop PV alone does not imply an Urban label.",
      "domain_ids": [
        "energy"
      ]
    },
    {
      "id": "ENE-02",
      "name": "Grids and energy storage",
      "definition": "Transmission, distribution, interconnection, flexibility, storage and network resilience.",
      "routing_rule": "A generating plant without grid measures belongs to ENE-01 or ENE-05.",
      "domain_ids": [
        "energy"
      ]
    },
    {
      "id": "ENE-03",
      "name": "Clean heating and fuels",
      "definition": "District heating, heat pumps, renewable heat and lower-emission fuel switching.",
      "routing_rule": "Vehicle fuel measures use TRN-01; building retrofit packages may also use URB-01.",
      "domain_ids": [
        "energy"
      ]
    },
    {
      "id": "ENE-04",
      "name": "Energy efficiency and demand management",
      "definition": "Energy audits, performance standards, efficient equipment and demand management.",
      "routing_rule": "Prefer a more specific building, industrial or transport topic when applicable.",
      "domain_ids": [
        "energy"
      ]
    },
    {
      "id": "ENE-05",
      "name": "Fossil energy transition",
      "definition": "Coal/oil/gas transition, fossil asset retirement, subsidy reform and supply changes.",
      "routing_rule": "Do not infer transition success from a plan or fuel switch.",
      "domain_ids": [
        "energy"
      ]
    },
    {
      "id": "ENE-06",
      "name": "Oil and gas methane",
      "definition": "Fugitive emissions, leaks, venting and flaring across oil/gas supply.",
      "routing_rule": "Landfill methane uses WST-02; agricultural methane uses AGR-03.",
      "domain_ids": [
        "energy"
      ]
    },
    {
      "id": "AGR-01",
      "name": "Irrigation efficiency",
      "definition": "Agricultural water delivery, irrigation modernization and water-saving technologies.",
      "routing_rule": "Municipal water supply uses WAT-01; solar irrigation may also use ENE-01.",
      "domain_ids": [
        "agriculture",
        "water"
      ]
    },
    {
      "id": "AGR-02",
      "name": "Resilient crops and soils",
      "definition": "Crop varieties, soil health, erosion control, land management and resilient farming.",
      "routing_rule": "Forest management uses BIO-01; record explicit carbon accounting under CLM-07.",
      "domain_ids": [
        "agriculture"
      ]
    },
    {
      "id": "AGR-03",
      "name": "Livestock and manure",
      "definition": "Animal health/resilience, feed, manure and agricultural methane/nitrous oxide measures.",
      "routing_rule": "Human health uses HEA topics.",
      "domain_ids": [
        "agriculture"
      ]
    },
    {
      "id": "AGR-04",
      "name": "Food systems and farm livelihoods",
      "definition": "Food security, agricultural advice, storage, value chains and farm livelihoods.",
      "routing_rule": "Food-waste disposal can also use WST-01 when a distinct measure is stated.",
      "domain_ids": [
        "agriculture"
      ]
    },
    {
      "id": "WAT-01",
      "name": "Water supply and groundwater",
      "definition": "Water availability, abstraction, groundwater, drinking water, storage and network losses.",
      "routing_rule": "Farm irrigation uses AGR-01; sanitation uses WST-03.",
      "domain_ids": [
        "water"
      ]
    },
    {
      "id": "WAT-02",
      "name": "River basins and drought management",
      "definition": "Basin management, allocation, drought planning, environmental flows and shared waters.",
      "routing_rule": "Flood defenses use WAT-03; warnings may also use CLM-04.",
      "domain_ids": [
        "water"
      ]
    },
    {
      "id": "WAT-03",
      "name": "Flood and coastal protection",
      "definition": "River/coastal flood risk, defenses, erosion and sea-level adaptation.",
      "routing_rule": "General settlement planning may additionally use URB-02.",
      "domain_ids": [
        "water"
      ]
    },
    {
      "id": "WAT-04",
      "name": "Water quality and reuse",
      "definition": "Surface-water quality, pollution prevention, safe reuse and receiving-water protection.",
      "routing_rule": "Wastewater treatment systems use WST-03; keep both if both purposes are explicit.",
      "domain_ids": [
        "water"
      ]
    },
    {
      "id": "BIO-01",
      "name": "Forest health and management",
      "definition": "Forest condition, sustainable management, wildfire/pest control and forest resilience.",
      "routing_rule": "Carbon-only forest targets use CLM-07 without an inferred biodiversity claim.",
      "domain_ids": [
        "biodiversity"
      ]
    },
    {
      "id": "BIO-02",
      "name": "Species, habitats and protected areas",
      "definition": "Species conservation, habitats, connectivity and terrestrial/aquatic protected areas.",
      "routing_rule": "Active ecosystem restoration uses BIO-03.",
      "domain_ids": [
        "biodiversity"
      ]
    },
    {
      "id": "BIO-03",
      "name": "Ecosystem restoration",
      "definition": "Restoration of forests, wetlands, peatlands and ecosystems, including ecosystem adaptation.",
      "routing_rule": "Record carbon or adaptation co-benefits only with evidence.",
      "domain_ids": [
        "biodiversity"
      ]
    },
    {
      "id": "HEA-01",
      "name": "Heat and human health",
      "definition": "Heat-health plans, cooling access, exposure and vulnerable-group protection.",
      "routing_rule": "Urban greening uses URB-03 when the physical intervention is stated.",
      "domain_ids": [
        "health"
      ]
    },
    {
      "id": "HEA-02",
      "name": "Climate-sensitive disease and exposure",
      "definition": "Infectious disease, water/vector-borne illness, air-quality exposure and surveillance.",
      "routing_rule": "Do not assume health outcomes from emissions reductions alone.",
      "domain_ids": [
        "health"
      ]
    },
    {
      "id": "HEA-03",
      "name": "Resilient health services",
      "definition": "Health facilities, service delivery, emergency capacity, staffing and essential supplies.",
      "routing_rule": "General civil protection uses CLM-04.",
      "domain_ids": [
        "health"
      ]
    },
    {
      "id": "URB-01",
      "name": "Building energy performance",
      "definition": "Building insulation, retrofits, performance codes, passive design and energy-saving systems.",
      "routing_rule": "Urban is a taxonomy domain here, not proof of urban geographic scope.",
      "domain_ids": [
        "urban",
        "energy"
      ]
    },
    {
      "id": "URB-02",
      "name": "Resilient settlements and infrastructure",
      "definition": "Spatial planning, building safety, urban drainage and local infrastructure resilience.",
      "routing_rule": "Sector-specific transport or energy networks use their specific topics.",
      "domain_ids": [
        "urban"
      ]
    },
    {
      "id": "URB-03",
      "name": "Urban cooling and green spaces",
      "definition": "Trees, green/blue spaces, shading and cooling-oriented public-space design.",
      "routing_rule": "General forest restoration uses BIO-03; health links require explicit evidence.",
      "domain_ids": [
        "urban"
      ]
    },
    {
      "id": "WST-01",
      "name": "Materials, recycling and circularity",
      "definition": "Prevention, separate collection, recycling, composting, food waste and circular material use.",
      "routing_rule": "Landfill gas uses WST-02; industrial production measures may use IND-01.",
      "domain_ids": [
        "waste"
      ]
    },
    {
      "id": "WST-02",
      "name": "Solid-waste disposal and methane",
      "definition": "Landfill management/emissions, gas capture and disposal-facility resilience.",
      "routing_rule": "Oil/gas methane uses ENE-06.",
      "domain_ids": [
        "waste"
      ]
    },
    {
      "id": "WST-03",
      "name": "Wastewater and sanitation",
      "definition": "Sewage, wastewater treatment, sanitation, sludge and associated emissions/resilience.",
      "routing_rule": "Receiving-water quality/reuse measures may also use WAT-04.",
      "domain_ids": [
        "waste",
        "water"
      ]
    },
    {
      "id": "TRN-01",
      "name": "Low-emission vehicles and fuels",
      "definition": "Electrification, charging, cleaner transport fuels and vehicle standards.",
      "routing_rule": "Public transport service improvements use TRN-02 where relevant.",
      "domain_ids": [
        "transport"
      ]
    },
    {
      "id": "TRN-02",
      "name": "Public, active and shared mobility",
      "definition": "Public transport, rail shift, walking, cycling and reduced private-car dependence.",
      "routing_rule": "Transport hazard resilience uses TRN-03.",
      "domain_ids": [
        "transport"
      ]
    },
    {
      "id": "TRN-03",
      "name": "Resilient transport networks",
      "definition": "Protection/adaptation of roads, railways, ports, airports and logistics.",
      "routing_rule": "Emissions measures use TRN-01 or TRN-02.",
      "domain_ids": [
        "transport"
      ]
    },
    {
      "id": "IND-01",
      "name": "Cleaner production and industrial efficiency",
      "definition": "Industrial energy/material efficiency, production technology, modernization and factory resilience.",
      "routing_rule": "Process gases/refrigerants use IND-02.",
      "domain_ids": [
        "industry"
      ]
    },
    {
      "id": "IND-02",
      "name": "Process emissions and refrigerants",
      "definition": "Industrial process emissions, cement/chemicals, fluorinated gases and refrigerants.",
      "routing_rule": "Generic factory energy efficiency uses IND-01.",
      "domain_ids": [
        "industry"
      ]
    },
    {
      "id": "TOU-01",
      "name": "Tourism adaptation and destination resilience",
      "definition": "Destination risks, changing seasons, diversification and resilient visitor infrastructure.",
      "routing_rule": "Only use Tourism when the sector is explicit.",
      "domain_ids": [
        "tourism"
      ]
    },
    {
      "id": "TOU-02",
      "name": "Tourism resource efficiency",
      "definition": "Tourism-specific water, energy, waste and sustainable visitor/accommodation measures.",
      "routing_rule": "Keep sector topics too where the source explicitly describes the intervention.",
      "domain_ids": [
        "tourism"
      ]
    },
    {
      "id": "CLM-08",
      "name": "Disaster risk and management",
      "definition": "Cross-sector all-hazards risk context, disaster governance, emergency response, relief and recovery arrangements.",
      "routing_rule": "Use for substantive cross-sector disaster material without a fitting narrower topic. Prefer CLM-04 for warning/readiness and sector topics for sector measures. Select specific risk functions separately; do not add this topic to every hazard mention or infer climate causation.",
      "domain_ids": [
        "climate"
      ]
    }
  ]
}

{
  "version": "3.0.1",
  "status": "Project codebook; not an official exhaustive UNDP or UNDRR classification",
  "scope": "Versioned project codebook. Policy classifications, linked facts, and evidence/processing metadata have separate sections. Classify only substantive supported meaning; lists may be empty.",
  "references": [
    {
      "title": "UNDRR terminology and DRR glossary",
      "url": "https://www.undrr.org/drr-glossary",
      "use": "Conceptual reference for risk terminology; the compact project facets and hazard list are our operational choices."
    },
    {
      "title": "UNDP NDC Implementation Guide",
      "url": "https://climatepromise.undp.org/research-and-reports/ndc-implementation-guide",
      "use": "Reference for implementation, finance, monitoring and policy alignment needs."
    },
    {
      "title": "UNDRR: mitigation terminology",
      "url": "https://www.undrr.org/terminology/mitigation",
      "use": "Distinguishes disaster-impact mitigation from climate mitigation; checked 8 October 2026."
    }
  ],
  "domain_definitions": {
    "climate": "Cross-sector climate and disaster policy, risk information, preparedness, finance and climate-wide commitments. Membership does not establish climate causation or an adaptation objective.",
    "energy": "Energy supply, demand, efficiency, renewables and energy systems.",
    "agriculture": "Farming, livestock, agricultural production and food systems.",
    "water": "Water resources, supply, irrigation and water management.",
    "biodiversity": "Species, habitats, ecosystems and biodiversity conservation.",
    "health": "Human health systems and climate/disaster-related health needs.",
    "urban": "Settlements, buildings, urban planning and municipal services.",
    "waste": "Solid waste, wastewater and waste-related emissions or management.",
    "transport": "Mobility, transport services and transport infrastructure.",
    "industry": "Industrial production, processes, efficiency and emissions.",
    "tourism": "Tourism systems, destinations and climate/disaster resilience."
  },
  "dimensions": [
    {
      "id": "objectives",
      "label": "Objectives",
      "question": "What policy purpose is evidenced?",
      "rule": "Choose only source-supported purposes; a NAP location alone does not establish adaptation. Mitigation here means emissions reduction or carbon sinks. Disaster-impact mitigation (such as flood mitigation) belongs to disaster risk reduction when supported; a word match alone is insufficient.",
      "options": [
        {
          "id": "adaptation",
          "label": "Adaptation",
          "definition": "Adjustment to actual or expected climate effects and their consequences."
        },
        {
          "id": "mitigation",
          "label": "Climate mitigation",
          "definition": "Reduction of greenhouse-gas emissions or enhancement of carbon sinks."
        },
        {
          "id": "disaster_risk_reduction",
          "label": "Disaster risk reduction",
          "definition": "Prevention of new disaster risk, reduction of existing risk, or management of residual risk."
        },
        {
          "id": "unspecified",
          "label": "Unspecified",
          "definition": "The purpose is relevant but cannot be determined from this evidence."
        }
      ],
      "category": "policy"
    },
    {
      "id": "record_kinds",
      "label": "Statement types",
      "question": "What does this claim assert?",
      "rule": "Choose one type per coherent claim. Split independently actionable measures and promises from observations. Keep target variants together. Historical periods belong in dates; templates belong in coverage exclusions. An actionable source priority is a commitment with its priority wording retained in details.",
      "options": [
        {
          "id": "context",
          "label": "Context / finding",
          "definition": "A source-described condition, risk, need or background finding without an actionable undertaking."
        },
        {
          "id": "priority",
          "label": "Priority",
          "definition": "An explicitly important area or goal without a concrete undertaking."
        },
        {
          "id": "proposal",
          "label": "Proposal / recommendation",
          "definition": "An action suggested, advised or considered without established adoption."
        },
        {
          "id": "commitment",
          "label": "Commitment",
          "definition": "An attributable undertaking to act or achieve a target, including qualitative and conditional commitments. Preserve source authority and draft/adopted status."
        },
        {
          "id": "implementation_observation",
          "label": "Implementation reported",
          "definition": "An attributed report of activity or delivery, such as installation or programme operation; not independent verification."
        },
        {
          "id": "result_observation",
          "label": "Result reported",
          "definition": "An attributed report of an outcome associated with an action; preserve period and method. Delivery of an output alone is implementation."
        },
        {
          "id": "projection",
          "label": "Projection",
          "definition": "An estimated future condition or effect based on assumptions or modelling; never an achieved result."
        },
        {
          "id": "scenario",
          "label": "Scenario",
          "definition": "A hypothetical pathway or set of future assumptions. A projection using a scenario remains a projection with scenario details."
        },
        {
          "id": "unclear",
          "label": "Unclear",
          "definition": "The evidence does not support a reliable statement classification. Explain the material uncertainty."
        }
      ],
      "category": "policy"
    },
    {
      "id": "temporal_roles",
      "label": "Temporal roles",
      "question": "How does an edition relate to the selected period?",
      "rule": "Do not infer supersession from a later filename or upload timestamp.",
      "options": [
        {
          "id": "current",
          "label": "Current",
          "definition": "The variant applies to the selected current reporting scope."
        },
        {
          "id": "historical",
          "label": "Historical",
          "definition": "Retained to describe an earlier period."
        },
        {
          "id": "superseded",
          "label": "Superseded",
          "definition": "Evidence explicitly establishes replacement by another variant."
        },
        {
          "id": "parallel",
          "label": "Parallel",
          "definition": "Coexisting variants, such as conditional scenarios, without established replacement."
        },
        {
          "id": "unresolved",
          "label": "Unresolved",
          "definition": "The temporal relationship remains uncertain."
        }
      ],
      "category": "evidence"
    },
    {
      "id": "conditionalities",
      "label": "Conditionalities",
      "question": "Does delivery depend on a stated condition?",
      "rule": "A financing mention alone does not prove conditionality. Keep conditions next to headline numbers.",
      "options": [
        {
          "id": "explicitly_conditional",
          "label": "Explicitly conditional",
          "definition": "The source explicitly makes the action or target dependent on support or another condition."
        },
        {
          "id": "explicitly_unconditional",
          "label": "Explicitly unconditional",
          "definition": "The source explicitly describes the action or target as unconditional."
        },
        {
          "id": "not_stated",
          "label": "Not stated",
          "definition": "The selected source states no condition; do not relabel this as unconditional."
        },
        {
          "id": "unclear",
          "label": "Unclear",
          "definition": "Conditional wording exists but its scope or meaning is uncertain."
        }
      ],
      "category": "detail"
    },
    {
      "id": "hazards",
      "label": "Hazards",
      "question": "Which potentially damaging process is discussed?",
      "rule": "Apply only to supported content. A hazard is not exposure or vulnerability. This compact list is not the complete UNDRR hazard classification.",
      "options": [
        {
          "id": "flood",
          "label": "Flood",
          "definition": "Water inundating land that is normally dry."
        },
        {
          "id": "drought",
          "label": "Drought",
          "definition": "A sustained precipitation or water deficit affecting systems or people."
        },
        {
          "id": "extreme_heat",
          "label": "Extreme heat",
          "definition": "Unusually high temperatures or heat episodes."
        },
        {
          "id": "wildfire",
          "label": "Wildfire",
          "definition": "Uncontrolled vegetation fire."
        },
        {
          "id": "storm",
          "label": "Storm",
          "definition": "Damaging wind or storm conditions; preserve the specific storm type in the source text."
        },
        {
          "id": "sea_level_rise",
          "label": "Sea level rise",
          "definition": "Rising average sea level affecting coastal systems."
        },
        {
          "id": "coastal_erosion",
          "label": "Coastal erosion",
          "definition": "Loss or retreat of coastal land through erosion."
        },
        {
          "id": "landslide",
          "label": "Landslide",
          "definition": "Downslope movement of soil, rock or debris."
        },
        {
          "id": "avalanche",
          "label": "Avalanche",
          "definition": "Rapid downslope movement of snow or ice."
        },
        {
          "id": "glacial_lake_outburst",
          "label": "Glacial lake outburst",
          "definition": "Sudden release of water from a glacial lake."
        },
        {
          "id": "water_scarcity",
          "label": "Water scarcity",
          "definition": "Insufficient usable water relative to demand; distinguish drivers from drought when stated."
        },
        {
          "id": "extreme_cold",
          "label": "Extreme cold",
          "definition": "Unusually low temperatures or cold episodes."
        },
        {
          "id": "disease",
          "label": "Disease",
          "definition": "A disease-related threat; preserve pathogen, vector and climate linkage where stated."
        },
        {
          "id": "earthquake",
          "label": "Earthquake",
          "definition": "Ground shaking or associated seismic threat; not automatically climate-related."
        },
        {
          "id": "tsunami",
          "label": "Tsunami",
          "definition": "Large sea waves generated by displacement; not automatically climate-related."
        },
        {
          "id": "technological_accident",
          "label": "Technological accident",
          "definition": "Accidental technological or industrial threat."
        },
        {
          "id": "compound_hazard",
          "label": "Compound hazard",
          "definition": "Interacting or concurrent hazards explicitly discussed together."
        },
        {
          "id": "other",
          "label": "Other",
          "definition": "A supported hazard outside this compact list; retain the exact source term in unmapped_terms."
        }
      ],
      "category": "policy"
    },
    {
      "id": "risk_functions",
      "label": "Risk and resilience functions",
      "question": "What specific risk function is described or supported?",
      "rule": "Select every substantively supported function, without duplicating the record. Leave irrelevant or unresolved functions empty. A generic resilience reference is not evidence of several functions. Co-occurring hazards and functions do not establish every possible relationship; split independent actions or explain the relationship in linked risk details.",
      "options": [
        {
          "id": "risk_understanding",
          "label": "Risk understanding",
          "definition": "Assess hazards, exposure, vulnerability and risk, or develop relevant risk information."
        },
        {
          "id": "risk_prevention_reduction",
          "label": "Risk prevention and reduction",
          "definition": "Avoid new risk or reduce existing exposure, vulnerability or potential harm."
        },
        {
          "id": "early_warning_preparedness",
          "label": "Early warning and preparedness",
          "definition": "Build warning capability, contingency plans, exercises and readiness to act."
        },
        {
          "id": "anticipatory_action",
          "label": "Anticipatory action",
          "definition": "Act ahead of a predicted event using a forecast, warning or trigger. General readiness alone is insufficient."
        },
        {
          "id": "emergency_response",
          "label": "Emergency response",
          "definition": "Protect people and meet urgent needs during or immediately after an event."
        },
        {
          "id": "recovery_reconstruction",
          "label": "Recovery and reconstruction",
          "definition": "Restore affected livelihoods, infrastructure and services, including rebuilding more safely."
        },
        {
          "id": "coping_continuity",
          "label": "Coping and continuity",
          "definition": "Maintain essential functions during disruption through buffers, redundancy or backup arrangements."
        },
        {
